mapper.select:
select cbs.id, ci.id as customerId, ci.code, ci,name, ci.short_name as shortName, ci.use_org_id as useOrgId, cbs.origin_seller_name as originSellerName, cbs.change_seller_name as changeSellerName, cbs.approve_status as approveStatus, cbs.approve_user_name as approveUserName, cbs.create_user_name as createUserName, cbs.create_time as createTime, cbs.start_date as startDate, cbs.approve_time as approveTime from customer_b2b_seller_change cbs inner join customer_info ci on cbs.main_id = ci.id where ${params.sqlMap.default} and cbs.is_deleted = false and ci.is_deleted = false ORDER BY
${item.field} ${item.sort}
cbs.create_time desc
